void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec2 center = vec2(0.5, 0.5);
    float radius = 0.4;
    float angle = atan(uv.y - center.y, uv.x - center.x);
    float dist = distance(uv, center);

    vec3 color = vec3(0.0);

    if (dist < radius) {
        float featherAngle = angle * 10.0;
        float featherDist = sin(featherAngle) * 0.1;
        float featherRadius = radius + featherDist;

        if (dist < featherRadius) {
            // Основной цвет
            color = vec3(0.5, 0.2, 0.1);

            // Добавляем цветной узор в виде множества маленьких глаз
            float eyeCount = 20.0;
            float eyeSpacing = 0.05;
            float eyeSize = 0.01;
            float beamCount = 10.0;
            for (float i = 0.0; i < beamCount; i++) {
                float beamAngle = i * 2.0 * 3.14159 / beamCount;
                for (float j = 0.0; j < eyeCount; j++) {
                    float eyeRadius = 0.1 + j * 0.05;
                    float eyeX = center.x + cos(beamAngle + j * 0.1) * eyeRadius;
                    float eyeY = center.y + sin(beamAngle + j * 0.1) * eyeRadius;
                    float eyeDist = distance(uv, vec2(eyeX, eyeY));
                    if (eyeDist < eyeSize) {
                        // Зрачок
                        if (eyeDist < eyeSize / 2.0) {
                            color = vec3(0.0, 0.0, 0.0); // черный
                        } else {
                            color = vec3(1.0, 1.0, 1.0); // белый
                        }

                        // Радужка
                        if (j < 5.0) {
                            color = mix(color, vec3(1.0, 0.5, 0.0), 0.5); // оранжевый
                        } else if (j < 10.0) {
                            color = mix(color, vec3(0.0, 1.0, 0.5), 0.5); // зеленый
                        } else if (j < 15.0) {
                            color = mix(color, vec3(0.5, 0.0, 1.0), 0.5); // синий
                        } else if (j < 20.0) {
                            color = mix(color, vec3(1.0, 0.0, 0.5), 0.5); // розовый
                        }

                        // Добавляем еще больше цветов
                        if (i < 5.0) {
                            color = mix(color, vec3(1.0, 1.0, 0.0), 0.2); // желтый
                        } else if (i < 10.0) {
                            color = mix(color, vec3(0.0, 1.0, 1.0), 0.2); // голубой
                        }
                    }
                }
            }
        }
    }

    // Добавляем тень
    if (dist > radius * 0.9) {
        color *= 0.5;
    }

    fragColor = vec4(color, 1.0);
}
